#include <bits/stdc++.h>
using namespace std;

//Start
typedef long long ll;
typedef double db;
#define mp(a,b) make_pair((a),(b))
#define x first
#define y second
#define bg begin()
#define ed end()
#define sz(a) int((a).size())
#define pb(a) push_back(a)
#define R(i,a,b) for(int i=(a),i##E=(b);i<i##E;i++)
#define L(i,a,b) for(int i=(b)-1,i##E=(a)-1;i>i##E;i--)
const int iinf=0x3f3f3f3f;
const ll linf=0x3f3f3f3f3f3f3f3f;

//Data
const int N=50;
int n,m,k,c,d,mxt;

//Flows
const int fN=(N*3+1)*N+2;
int s,t,fn;
vector<int> e[fN],to,fw,co;
void adde(int u,int v,int w,int c){
    e[u].pb(sz(to)),to.pb(v),fw.pb(w),co.pb(+c);
    e[v].pb(sz(to)),to.pb(u),fw.pb(0),co.pb(-c);
}
int dep[fN],pre[fN]; bool vis[fN];
bool spfa(){
    fill(dep,dep+fn,iinf),fill(pre,pre+fn,-1),fill(vis,vis+fn,false);
    queue<int> q; q.push(s),vis[s]=true,dep[s]=0;
    while(sz(q)){
        int u=q.front(); q.pop(),vis[u]=false;
        for(int v:e[u])if(fw[v]&&dep[to[v]]>dep[u]+co[v])
            dep[to[v]]=dep[u]+co[v],pre[to[v]]=v,
            (!vis[to[v]])&&(q.push(to[v]),vis[to[v]]=true);
    }
    return dep[t]<iinf;
}
pair<int,int> mcmf(){
    pair<int,int> res(0,0);
    while(spfa()){
        int f=iinf;
        for(int u=t;u!=s;u=to[pre[u]^1]) f=min(f,fw[pre[u]]);
        for(int u=t;u!=s;u=to[pre[u]^1]) fw[pre[u]]-=f,fw[pre[u]^1]+=f;
        res.x+=f,res.y+=dep[t]*f;
    }
    return res;
}

//Main
int main(){
    ios::sync_with_stdio(0);
    cin.tie(0),cout.tie(0);
    cin>>n>>m>>k>>c>>d,mxt=N*3+1;
    fn=(t=(s=n*mxt)+1)+1;
    R(i,0,k){int u;cin>>u,--u,adde(s,u,1,0);}
    while(m--){
        int u,v; cin>>u>>v,--u,--v;
        R(i,0,mxt-1)R(p,1,k+1)
            adde(i*n+u,(i+1)*n+v,1,2*d*p-d),
            adde(i*n+v,(i+1)*n+u,1,2*d*p-d);
    }
    R(u,0,n)R(i,0,mxt-1) adde(i*n+u,(i+1)*n+u,k,0);
    R(i,0,mxt) adde(i*n,t,k,i*c);
    pair<int,int> ans=mcmf();
    assert(ans.x==k);
    cout<<ans.y<<'\n';
    return 0;
